from dataclasses import dataclass
from datetime import datetime, timezone
from typing import Optional


class ExpiredPromotionError(Exception):
    """Raised when an order uses a promotion past its expiry.

    Policy is provisional (product undecided): reject the order.
    """

    def __init__(self, code: str):
        super().__init__(f"Promotion {code!r} has expired")
        self.code = code


@dataclass(frozen=True)
class Promotion:
    code: str
    percent_off: int
    expires_at: datetime  # timezone-aware


def checkout_total(subtotal_cents: int, promotion: Optional[Promotion] = None,
                   now: Optional[datetime] = None) -> int:
    now = now or datetime.now(timezone.utc)
    if promotion is None:
        return subtotal_cents
    if promotion.expires_at <= now:
        raise ExpiredPromotionError(promotion.code)
    return subtotal_cents - subtotal_cents * promotion.percent_off // 100
