import unittest
from datetime import datetime, timedelta, timezone

from checkout import ExpiredPromotionError, Promotion, checkout_total

NOW = datetime(2026, 11, 16, 12, tzinfo=timezone.utc)


def promo(delta):
    return Promotion("SAVE10", 10, NOW + delta)


class CheckoutTest(unittest.TestCase):
    def test_no_promotion(self):
        self.assertEqual(checkout_total(1000, None, NOW), 1000)

    def test_valid_promotion_applied(self):
        self.assertEqual(checkout_total(1000, promo(timedelta(days=1)), NOW), 900)

    def test_expired_promotion_rejects_order(self):
        with self.assertRaises(ExpiredPromotionError) as cm:
            checkout_total(1000, promo(-timedelta(seconds=1)), NOW)
        self.assertEqual(cm.exception.code, "SAVE10")

    def test_promotion_expiring_exactly_now_is_expired(self):
        with self.assertRaises(ExpiredPromotionError):
            checkout_total(1000, promo(timedelta(0)), NOW)


if __name__ == "__main__":
    unittest.main()
